CREATE TABLE "Organization" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT UNIQUE,"publicCode" TEXT UNIQUE,"createdAt" TIMESTAMP NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE "AppUser" ("id" TEXT PRIMARY KEY,"organizationId" TEXT REFERENCES "Organization"("id"),"email" TEXT NOT NULL UNIQUE,"loginId" TEXT,"displayName" TEXT,"passwordHash" TEXT,"role" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"isSharedStoreAccount" BOOLEAN NOT NULL DEFAULT FALSE,"createdAt" TIMESTAMP NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE "BillingPlan" ("planKey" TEXT PRIMARY KEY,"displayName" TEXT,"monthlyAmount" INTEGER,"active" BOOLEAN DEFAULT TRUE);
CREATE TABLE "OrganizationBilling" ("organizationId" TEXT PRIMARY KEY REFERENCES "Organization"("id"),"planKey" TEXT,"onboardingStatus" TEXT,"subscriptionStatus" TEXT,"billingRequiredAt" TIMESTAMP,"stripeCheckoutSessionId" TEXT,"createdAt" TIMESTAMP DEFAULT NOW(),"updatedAt" TIMESTAMP DEFAULT NOW());
CREATE TABLE "WholesaleDealerBilling" ("onboardingStatus" TEXT,"subscriptionStatus" TEXT,"stripeCheckoutSessionId" TEXT,"updatedAt" TIMESTAMP);
CREATE TABLE "OrganizationStoreProfile" ("organizationId" TEXT PRIMARY KEY REFERENCES "Organization"("id"),"ownerName" TEXT,"phone" TEXT,"prefecture" TEXT,"city" TEXT,"addressLine1" TEXT,"orimiaPublished" BOOLEAN DEFAULT TRUE);
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "Organization"("id"),"name" TEXT NOT NULL,"updatedAt" TIMESTAMP NOT NULL,"deletedAt" TIMESTAMP,"storeHiddenAt" TIMESTAMP);
CREATE TABLE "ServiceSale" ("id" TEXT PRIMARY KEY,"customerId" TEXT NOT NULL REFERENCES "Customer"("id"),"title" TEXT NOT NULL,"amount" INTEGER NOT NULL,"paidAt" TIMESTAMP NOT NULL);
CREATE TABLE "Appointment" ("id" TEXT PRIMARY KEY,"customerId" TEXT NOT NULL REFERENCES "Customer"("id"),"scheduledAt" TIMESTAMP NOT NULL,"status" TEXT,"updatedAt" TIMESTAMP NOT NULL);
CREATE TABLE "StaffBookingSetting" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES "Organization"("id"),"staffName" TEXT NOT NULL,"staffKey" TEXT NOT NULL,"updatedAt" TIMESTAMP NOT NULL,"active" BOOLEAN DEFAULT TRUE);
